// Bundles the compiled server into one file so the plugin folder can be installed
// straight from Git (no npm install on the user's machine). Output is committed.
import { build } from 'esbuild';
import { mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const outfile = join(root, 'plugin', 'server', 'index.js');
mkdirSync(dirname(outfile), { recursive: true });
await build({
  entryPoints: [join(root, 'dist', 'index.js')],
  outfile,
  bundle: true,
  platform: 'node',
  format: 'esm',
  target: 'node22',
  legalComments: 'none',
  logLevel: 'warning',
  banner: { js: [
    '// Generated by `npm run build:bundle` from src/. Do not edit; rebuild instead.',
    "import { createRequire as __createRequire } from 'node:module';",
    'const require = __createRequire(import.meta.url);',
  ].join('\n') },
});
console.log(`Bundle written: ${outfile}`);
